SELECT p.product_id, p.name, p.author, p.publisher, p.price, p.stock_quantity, p.status, c.category_name, p.created_at FROM product p LEFT JOIN category c ON p.category_id = c.category_id WHERE p.deleted_at IS NULL
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND ( p.name LIKE CONCAT('%', #{keyword}, '%') OR p.author LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM product p
WHERE p.deleted_at IS NULL


    AND category_id = #{categoryId}



    AND p.status = #{status}



    AND (
    p.name LIKE CONCAT('%', #{keyword}, '%')
    OR p.author LIKE CONCAT('%', #{keyword}, '%')
